mapper.select:
SELECT c.id, c.card_no, c.owner_id, c.card_type, c.status, c.building_ids, c.valid_from, c.valid_to, c.remark, c.create_time, c.update_time, u.real_name AS owner_name, u.phone AS owner_phone FROM access_card c LEFT JOIN sys_user u ON c.owner_id = u.id
AND c.owner_id = #{ownerId}
AND c.card_type = #{cardType}
AND c.status = #{status}
AND (c.card_no LIKE CONCAT('%', #{keyword}, '%') OR u.real_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY c.create_time DESC
